using System;
using System.Runtime.CompilerServices;
using System.Threading;

namespace EasyEcs;

// Component access and the structural changes that move an entity between archetype tables. The public T1..T9
// overloads are generated by EasyEcs.Generator.
public sealed partial class World
{
    /// <summary>
    /// Passes iterating this world right now (ForEach, query enumerators). While one runs, rows that lose their entity
    /// become tombstones that keep their data (the pass carries writes through its refs over to the entity's new row)
    /// instead of being filled by the last row; the last pass to end closes them (<see cref="EndPass"/>).
    /// </summary>
    internal int Passes;

    // Archetypes with tombstones, closed when the last pass ends (each registered once: Archetype.Dirty).
    private Archetype[] _dirty = new Archetype[8];
    private int _dirtyCount;

    /// <summary>Start a pass (rows that lose their entity become tombstones until it ends).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal void BeginPass() => Interlocked.Increment(ref Passes);

    /// <summary>End a pass; the last one to end closes the tombstones left by structural changes during passes.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal void EndPass()
    {
        if (Interlocked.Decrement(ref Passes) == 0 && _dirtyCount > 0) CloseTombstones();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private void CloseTombstones()
    {
        using (Structural())
        {
            if (Volatile.Read(ref Passes) != 0) return; // a pass started meanwhile: it will close them
            for (int i = 0; i < _dirtyCount; i++)
            {
                _dirty[i].FillHoles(Meta);
                _dirty[i] = null;
            }

            _dirtyCount = 0;
            StorageVersion++;
        }
    }

    /// <summary>Remove entity row <paramref name="slot"/> from <paramref name="archetype"/>. Inside the structural lock.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void RemoveRow(Archetype archetype, int slot)
    {
        if (!archetype.Remove(slot, Meta, Volatile.Read(ref Passes) != 0)) return;
        if (_dirtyCount == _dirty.Length) Array.Resize(ref _dirty, _dirty.Length * 2);
        _dirty[_dirtyCount++] = archetype;
    }

    /// <summary>Ref to <typeparamref name="T"/> of entity <paramref name="id"/>, whose archetype must have it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal ref T ColumnRef<T>(ushort bit, int id) where T : struct, IComponent => ref Row<T>(ref MetaRef(id), bit);

    /// <summary>Ref to <typeparamref name="T"/> in the row of <paramref name="meta"/>, whose archetype must have it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static ref T Row<T>(scoped ref EntityMeta meta, ushort bit) where T : struct, IComponent =>
        ref Unsafe.Add(ref meta.Archetype.Base<T>(bit), meta.Slot);

    /// <summary>
    /// Add one component bit to entity <paramref name="id"/> (<paramref name="meta"/> is its record). When its table has
    /// the column the row only gets the component back; else the entity moves along the cached archetype edge (no
    /// mask hashing). Inside the structural lock.
    /// </summary>
    internal void AddBit(ref EntityMeta meta, int id, ushort bit)
    {
        var from = meta.Archetype;
        int column = from.ColumnIndex(bit);
        if (column >= 0)
        {
            if (from.Restore(column, meta.Slot)) StorageVersion++; // passes re-read presence bits
        }
        else MoveTo(ref meta, id, from.GetAddEdge(bit) ?? CreateEdge(from, bit));
    }

    /// <summary>
    /// Add several component bits in at most one archetype transition. The transition is cached per (source archetype,
    /// <paramref name="signature"/>), so only the first call of a signature from an archetype builds a mask. Inside the
    /// structural lock.
    /// </summary>
    internal void AddBits(ref EntityMeta meta, int id, ReadOnlySpan<ushort> bits, int signature)
    {
        var from = meta.Archetype;
        MoveTo(ref meta, id, from.GetAddSetEdge(signature) ?? CreateSetEdge(from, bits, signature));
        var archetype = meta.Archetype;
        if (!archetype.HasAbsent) return;
        for (int i = 0; i < bits.Length; i++)
            if (archetype.Restore(archetype.ColumnIndex(bits[i]), meta.Slot))
                StorageVersion++;
    }

    /// <summary>
    /// Remove one component bit: the row keeps its column and only loses the component (no move). A missing component
    /// is ignored. Inside the structural lock.
    /// </summary>
    internal void RemoveBit(ref EntityMeta meta, ushort bit)
    {
        var archetype = meta.Archetype;
        int column = archetype.ColumnIndex(bit);
        if (column >= 0 && archetype.Take(column, meta.Slot)) StorageVersion++; // passes re-read presence bits
    }

    /// <summary>Remove component bits (see <see cref="RemoveBit"/>). Inside the structural lock.</summary>
    internal void RemoveBits(ref EntityMeta meta, ReadOnlySpan<ushort> bits)
    {
        for (int i = 0; i < bits.Length; i++) RemoveBit(ref meta, bits[i]);
    }

    /// <summary>
    /// Move entity <paramref name="id"/> along <paramref name="transition"/>: copy its shared components into a row of
    /// the target table and remove its old row. Components only the target has are left for the caller to write.
    /// Inside the structural lock.
    /// </summary>
    private void MoveTo(ref EntityMeta meta, int id, Transition transition)
    {
        var target = transition.Target;
        if (ReferenceEquals(target, transition.Source)) return;

        int slot = target.Add(id, meta.Version);
        int oldSlot = meta.Slot;
        transition.CopyRow(oldSlot, slot);
        meta.Archetype = target;
        meta.Slot = slot;
        RemoveRow(transition.Source, oldSlot); // may move another entity into oldSlot (outside passes)
        StorageVersion++;
    }

    /// <summary>
    /// Whether <paramref name="to"/> (the entity's archetype, read without the lock) still has a column the job writes.
    /// When the job removed every component it writes (or destroyed the entity), there is nothing to carry over and
    /// the lock is skipped. Reading without the lock is safe here: component values have one owner thread (the one
    /// running the pass), so no other thread changes this entity's archetype meanwhile; the copy re-reads under the lock.
    /// </summary>
    private static bool KeepsAnyWritten(Archetype to, int writes, ReadOnlySpan<ushort> bits)
    {
        if (to == null) return false;
        for (int k = 0; k < bits.Length; k++)
            if ((writes >> k & 1) != 0 && to.ColumnIndex(bits[k]) >= 0)
                return true;
        return false;
    }

    /// <summary>
    /// After a pass's job changed the archetype of the entity it was visiting (row <paramref name="slot"/> of
    /// <paramref name="from"/> is a tombstone now): copy the components the job writes through its refs
    /// (<paramref name="writes"/>, bit k for <paramref name="bits"/>[k]) from the old row, where those writes landed,
    /// to the entity's new row. Nothing to do when the entity was destroyed. Cold path.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    internal void CarryOver(Archetype from, int slot, int id, int writes, ReadOnlySpan<ushort> bits)
    {
        if (writes == 0 || !KeepsAnyWritten(MetaRef(id).Archetype, writes, bits)) return;
        using (Structural())
        {
            ref var meta = ref MetaRef(id);
            var to = meta.Archetype;
            if (to == null || meta.Version != from.Versions[slot]) return; // destroyed (the id may be reused already)
            for (int k = 0; k < bits.Length; k++)
            {
                if ((writes >> k & 1) == 0) continue;
                int target = to.ColumnIndex(bits[k]);
                if (target < 0) continue; // removed by the job
                int source = from.ColumnIndex(bits[k]);
                Archetype.CopyElement(from.Info(source), from.Columns[source], slot, to.Columns[target], meta.Slot);
            }
        }
    }
}
